args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel ?deathPlace ?deathPlaceLabel ?deathPlaceLiteral WHERE {
  dbr:Salin_Mibaya dbp:father ?father .
  OPTIONAL { ?father dbo:deathPlace ?deathPlace . }
  OPTIONAL { ?father dbp:deathPlace ?deathPlaceLiteral . }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = "en") }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = "en") }
}

PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT DISTINCT ?deathPlaceLiteral WHERE {
  dbr:Bayin_Htwe dbp:deathPlace ?deathPlaceLiteral .
}

